const items = $input.all();
const raw_files = items.map(item => ({
  id: item.json.id,
  name: item.json.name,
  mimeType: item.json.mimeType
}));

const inventory_list = raw_files
  .map(f => `- ${f.name} (id: ${f.id})`)
  .join('\n');

return [{
  json: {
    raw_files,
    inventory_list,
    total_files: raw_files.length
  }
}];

