const fs = require('fs');

const first = $input.first().json;
let rawText = '';

if (first.content && Array.isArray(first.content) && first.content[0]?.text) {
  rawText = first.content[0].text;
} else if (typeof first === 'string') {
  rawText = first;
} else if (first.text) {
  rawText = first.text;
} else {
  rawText = JSON.stringify(first);
}

// Strip markdown code fences (```json ... ```)
const cleaned = rawText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
const parsed = JSON.parse(cleaned);

// Standardize timeline keys strictly to b_roll
const standardizedTimeline = (parsed.timeline || []).map((item, idx) => ({
  scene: typeof item.scene === 'number' ? item.scene : (idx + 1),
  start_time: parseFloat(item.start_time),
  end_time: parseFloat(item.end_time),
  b_roll: item.b_roll || item.b_roll_name || item.b_roll_id,
  text_overlay: item.text_overlay || ''
}));

const timelineData = {
  video_title: parsed.video_title || 'Untitled Ad',
  total_duration_seconds: parseFloat(parsed.total_duration_seconds || 0),
  voiceover_script: parsed.voiceover_script || '',
  timeline: standardizedTimeline
};

// Ensure workspace directories exist
fs.mkdirSync('/workspace/inputs', { recursive: true });
fs.mkdirSync('/workspace/outputs', { recursive: true });
fs.mkdirSync('/workspace/assets', { recursive: true });

// Save timeline JSON
fs.writeFileSync('/workspace/inputs/current_timeline.json', JSON.stringify(timelineData, null, 2), 'utf-8');

return [{ json: timelineData }];

const stdout = $input.first().json.stdout || '';
const lines = stdout.trim().split('\n');
const lastLine = lines[lines.length - 1].trim();

let judgeResult = { score: 0, feedback: 'Unable to parse judge output' };
try {
  judgeResult = JSON.parse(lastLine);
} catch (e) {
  const match = stdout.match(/\{[\s\S]*"score"[\s\S]*\}/);
  if (match) {
    try {
      judgeResult = JSON.parse(match[0]);
    } catch (err) {}
  }
}

// Retrieve timeline from Node 4b
const timelineData = $('4b. Save to current_timeline.json').first().json;

return [{
  json: {
    ...timelineData,
    score: typeof judgeResult.score === 'number' ? judgeResult.score : 0,
    feedback: judgeResult.feedback || '',
    judge_stdout: stdout
  }
}];

const fs = require('fs');

// 1. Decode Sarvam TTS base64 audio and save to /workspace/inputs/raw_tts.wav
const ttsJson = $input.first().json;
if (ttsJson.audios && Array.isArray(ttsJson.audios) && ttsJson.audios.length > 0) {
  const audioBase64 = ttsJson.audios[0];
  const audioBuffer = Buffer.from(audioBase64, 'base64');
  fs.mkdirSync('/workspace/inputs', { recursive: true });
  fs.writeFileSync('/workspace/inputs/raw_tts.wav', audioBuffer);
}

// 2. Load timeline from Node 4b and catalog from Node 3
const timelineData = $('4b. Save to current_timeline.json').first().json;
const catalogData = $('3. Build Drive File Catalog').first().json;
const rawFiles = catalogData.raw_files || [];

// Sequential serial naming: 01_filename.mp4, 02_filename.mp4, etc.
const serialMap = new Map();
let counter = 1;

timelineData.timeline = (timelineData.timeline || []).map(cut => {
  const originalName = cut.b_roll;
  if (!serialMap.has(originalName)) {
    const prefix = String(counter).padStart(2, '0');
    const serialName = `${prefix}_${originalName}`;

    // Find Drive file ID from catalog
    const matchedFile = rawFiles.find(f => 
      f.name === originalName || 
      f.name.toLowerCase() === (originalName || '').toLowerCase()
    );
    const fileId = matchedFile ? matchedFile.id : null;

    serialMap.set(originalName, {
      file_id: fileId,
      file_name: serialName,
      original_name: originalName
    });
    counter++;
  }

  const assigned = serialMap.get(originalName);
  return {
    ...cut,
    b_roll: assigned.file_name
  };
});

// Overwrite /workspace/inputs/current_timeline.json on disk with serial-numbered filenames
fs.writeFileSync(
  '/workspace/inputs/current_timeline.json',
  JSON.stringify(timelineData, null, 2),
  'utf-8'
);

// 3. Return one item per unique file to download
const downloadQueue = Array.from(serialMap.values()).map(item => ({
  json: {
    file_id: item.file_id,
    file_name: item.file_name,
    original_name: item.original_name
  }
}));

return downloadQueue;

// Wait for all downloads from Node 10 to complete before running MoviePy once
const items = $input.all();
return [{
  json: {
    ready: true,
    total_clips_downloaded: items.length
  }
}];

const fs = require('fs');

const videoPath = '/workspace/outputs/finished_ad.mp4';
const projectPath = '/workspace/outputs/edit_project_source.json';

const videoBuffer = fs.readFileSync(videoPath);
const projectBuffer = fs.readFileSync(projectPath);

return [
  {
