        fileName: 'finished_ad.mp4'
      }
    }
  },
  {
    json: {
      fileName: 'edit_project_source.json',
      folderId: 'PASTE_YOUR_OUTPUT_ID_HERE'
    },
    binary: {
      data: {
        data: projectBuffer.toString('base64'),
        mimeType: 'application/json',
        fileName: 'edit_project_source.json'
      }
    }
  }
];
